#!/bin/sh
# Regenerates the C that zudiff builds from its Goose source.
#
#   tools/regenerate.sh /path/to/goose-checkout            # rewrite src/
#   tools/regenerate.sh --verify /path/to/goose-checkout   # diff only
#
# The checkout must be at the commit in tools/goose/PIN, cloned from the
# repository in tools/goose/REMOTE, and already built
# (cmake -S . -B build && cmake --build build), so that build/goose exists.
# Nothing here runs at install time: CRAN machines have no Goose compiler,
# so the generated files are committed and shipped.
#
# Writes, from tools/goose/zudiff.goose and the checkout:
#   src/zudiff_goose.c  the compiled program, with no main
#   src/zudiff_goose.h  its exported functions
#   src/goose_version.h   the runtime interface hash the two halves share
#   src/goose_runtime.c   Goose's runtime (goose --emit-runtime)
# and records their checksums in tools/goose/PROVENANCE.

set -eu

verify=0
if [ "${1:-}" = "--verify" ]; then
  verify=1
  shift
fi
if [ $# -ne 1 ]; then
  echo "usage: $0 [--verify] <goose-checkout>" >&2
  exit 2
fi

pkg=$(cd "$(dirname "$0")/.." && pwd)
gsrc=$(cd "$1" && pwd)
goose="$gsrc/build/goose"
pin=$(cat "$pkg/tools/goose/PIN")
remote=$(cat "$pkg/tools/goose/REMOTE")

[ -x "$goose" ] || { echo "no compiler at $goose; build the checkout" >&2; exit 1; }
head=$(git -C "$gsrc" rev-parse HEAD)
if [ "$head" != "$pin" ]; then
  echo "goose checkout is at $head, tools/goose/PIN says $pin" >&2
  exit 1
fi

out=$(mktemp -d)
trap 'rm -rf "$out"' EXIT

# The compiler names source files by the path it was given. Run it from
# tools/goose so the package's own file is a bare name.
(cd "$pkg/tools/goose" &&
  "$goose" -o "$out/zudiff_goose.c" --header "$out/zudiff_goose.h" \
    zudiff.goose >/dev/null)

# The standard library is named by its absolute path in the checkout.
# Rewrite it so the output does not depend on where the checkout lives.
sed 's|"[^"]*/stdlib/\([A-Za-z0-9_]*\.goose\)"|"goose/stdlib/\1"|' \
  "$out/zudiff_goose.c" >"$out/tmp.c"
mv "$out/tmp.c" "$out/zudiff_goose.c"

version=$(sed -n 's/^#define GS_RUNTIME_VERSION \([0-9a-f]*\)$/\1/p' \
  "$out/zudiff_goose.c")
[ -n "$version" ] || { echo "no GS_RUNTIME_VERSION in generated C" >&2; exit 1; }
cat >"$out/goose_version.h" <<EOF
/* Generated by tools/regenerate.sh. The runtime interface hash of the
   Goose compiler at tools/goose/PIN: goose_runtime.c defines the
   start-up function under this name, so C generated by another compiler
   version fails to link instead of misbehaving. ZUDIFF_GOOSE_COMMIT is
   the pin itself, which zudiff_info() reports. */
#ifndef GOOSE_VERSION_H
#define GOOSE_VERSION_H
#define GS_RUNTIME_VERSION $version
#define ZUDIFF_GOOSE_COMMIT "$pin"
#endif
EOF

# Goose's runtime, whole, as the compiler writes it. src/Makevars builds
# it with -DGS_HOSTED: every failure returns to goose_host_call, and
# nothing ends the process or writes to stdout or stderr.
"$goose" --emit-runtime "$out/goose_runtime.c" >/dev/null

files="zudiff_goose.c zudiff_goose.h goose_version.h goose_runtime.c"

if [ "$verify" -eq 1 ]; then
  status=0
  for f in $files; do
    if ! cmp -s "$out/$f" "$pkg/src/$f"; then
      echo "src/$f differs from what tools/goose and the pin generate" >&2
      status=1
    fi
  done
  [ "$status" -eq 0 ] && echo "generated files match"
  exit "$status"
fi

for f in $files; do cp "$out/$f" "$pkg/src/$f"; done

{
  echo "# Written by tools/regenerate.sh. Do not edit."
  echo "goose_repository ${remote%.git}"
  echo "goose_commit $pin"
  echo "runtime_version $version"
  for f in $files; do
    echo "sha256 $(cd "$pkg/src" && sha256sum "$f")"
  done
} >"$pkg/tools/goose/PROVENANCE"

echo "regenerated $files at goose $pin"
